triggers.r06_pending_create:
CREATE TRIGGER r06_pending_create BEFORE UPDATE ON verification_limit_state WHEN OLD.pending_audit_event_id IS NULL AND NEW.pending_audit_event_id IS NOT NULL BEGIN
            SELECT CASE WHEN (strftime('%Y-%m-%d %H:%M:%S',CAST(NEW.last_observed_at/1000 AS INTEGER),'unixepoch') || printf('.%03d',NEW.last_observed_at % 1000)) IS NULL OR NEW.pending_audit_occurred_at IS NOT (strftime('%Y-%m-%d %H:%M:%S',CAST(NEW.last_observed_at/1000 AS INTEGER),'unixepoch') || printf('.%03d',NEW.last_observed_at % 1000)) OR coalesce(NEW.failure_10_at,NEW.failure_09_at,NEW.failure_08_at,NEW.failure_07_at,NEW.failure_06_at,NEW.failure_05_at,NEW.failure_04_at,NEW.failure_03_at,NEW.failure_02_at,NEW.failure_01_at) IS NOT NEW.last_observed_at THEN RAISE(ABORT,'R06 occurrence mismatch') END;
            SELECT CASE WHEN EXISTS(SELECT 1 FROM audit_logs WHERE id=NEW.pending_audit_event_id) THEN RAISE(ABORT,'R06 event already materialized') END;
            SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM phone_otp_challenges c JOIN otp_delivery_intents d ON d.challenge_id=c.id WHERE c.id=NEW.pending_audit_challenge_id AND c.merchant_id=NEW.merchant_id AND c.actor_user_id=NEW.actor_user_id AND c.purpose='application_phone' AND d.request_id=NEW.pending_audit_request_id AND d.merchant_id=NEW.merchant_id AND d.actor_user_id=NEW.actor_user_id AND ((NEW.pending_audit_reason_code='aggregate_exhausted' AND ((NEW.failure_01_at IS NOT NULL)+(NEW.failure_02_at IS NOT NULL)+(NEW.failure_03_at IS NOT NULL)+(NEW.failure_04_at IS NOT NULL)+(NEW.failure_05_at IS NOT NULL)+(NEW.failure_06_at IS NOT NULL)+(NEW.failure_07_at IS NOT NULL)+(NEW.failure_08_at IS NOT NULL)+(NEW.failure_09_at IS NOT NULL)+(NEW.failure_10_at IS NOT NULL))=10 AND c.failed_attempts BETWEEN 1 AND 5 AND c.state IN ('active','exhausted')) OR (NEW.pending_audit_reason_code='exhausted' AND ((NEW.failure_01_at IS NOT NULL)+(NEW.failure_02_at IS NOT NULL)+(NEW.failure_03_at IS NOT NULL)+(NEW.failure_04_at IS NOT NULL)+(NEW.failure_05_at IS NOT NULL)+(NEW.failure_06_at IS NOT NULL)+(NEW.failure_07_at IS NOT NULL)+(NEW.failure_08_at IS NOT NULL)+(NEW.failure_09_at IS NOT NULL)+(NEW.failure_10_at IS NOT NULL))<10 AND c.failed_attempts=5 AND c.state='exhausted' AND c.terminal_at=NEW.last_observed_at))) THEN RAISE(ABORT,'R06 pending lineage or threshold mismatch') END;
        END

triggers.r06_pending_discharge:
CREATE TRIGGER r06_pending_discharge BEFORE UPDATE ON verification_limit_state WHEN OLD.pending_audit_event_id IS NOT NULL AND NEW.pending_audit_event_id IS NULL BEGIN
            SELECT CASE WHEN (NEW.last_send_at IS NOT OLD.last_send_at OR NEW.failure_01_at IS NOT OLD.failure_01_at OR NEW.failure_02_at IS NOT OLD.failure_02_at OR NEW.failure_03_at IS NOT OLD.failure_03_at OR NEW.failure_04_at IS NOT OLD.failure_04_at OR NEW.failure_05_at IS NOT OLD.failure_05_at OR NEW.failure_06_at IS NOT OLD.failure_06_at OR NEW.failure_07_at IS NOT OLD.failure_07_at OR NEW.failure_08_at IS NOT OLD.failure_08_at OR NEW.failure_09_at IS NOT OLD.failure_09_at OR NEW.failure_10_at IS NOT OLD.failure_10_at) OR NEW.last_observed_at IS NOT OLD.last_observed_at OR NEW.updated_at IS NOT OLD.updated_at THEN RAISE(ABORT,'R06 discharge cannot alter accounting') END;
            SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM audit_logs a WHERE a.id=OLD.pending_audit_event_id AND a.event_type='otp.changed' AND a.actor_user_id=OLD.actor_user_id AND a.merchant_id=OLD.merchant_id AND a.target_user_id IS NULL AND a.application_id IS NULL AND a.request_id=OLD.pending_audit_request_id AND a.occurred_at=OLD.pending_audit_occurred_at AND a.metadata=('{"reason_code":"' || OLD.pending_audit_reason_code || '"}')) THEN RAISE(ABORT,'R06 exact audit required') END;
        END
